// WidgetContainer.tsx
import React, { useEffect, useState, useRef } from 'react'
import { ConfigProvider as AntdConfigProvider } from 'antd'
import { ConfigProvider as AntdMobileConfigProvider } from 'antd-mobile'
import { Toaster } from 'sonner'
import AppointmentBookingForm from '@/components/booking/AppointmentBookingForm'
import AppointmentBookingFormMobile from '@/components/booking/AppointmentBookingFormMobile'
import { useIsMobile } from '@/components/booking/hooks/useIsMobile'
import type { WidgetConfig } from '@/types/widget'
import enUS from 'antd/locale/en_US'
import enUSMobile from 'antd-mobile/es/locales/en-US'

// Import antd-mobile global styles - this is why it works in dev mode
//import 'antd-mobile/es/global';

import '@/styles/widget.css'

interface WidgetContainerProps {
  config: WidgetConfig
  onBookingComplete?: (bookingData: any) => void
  onError?: (error: any) => void
  onLoad?: (widgetId: string) => void
}

const WidgetContainer: React.FC<WidgetContainerProps> = ({
  config,
  onBookingComplete,
  onError,
  onLoad
}) => {
  const isMobile = useIsMobile()
  const [isLoaded, setIsLoaded] = useState(false)
  const [error, setError] = useState<string | null>(null)
  
  // Portal container ref for antd-mobile components
  const portalContainerRef = useRef<HTMLDivElement>(null)

  // Generate unique widget ID for this instance
  const [widgetId] = useState(`widget-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`)

  useEffect(() => {
    // Log portal container status for debugging
    if (portalContainerRef.current) {
      console.log('[BookingWidget] Portal container ready:', portalContainerRef.current)
    }
    
    // Simulate loading and call onLoad callback
    const timer = setTimeout(() => {
      setIsLoaded(true)
      onLoad?.(widgetId)
    }, 100)

    return () => clearTimeout(timer)
  }, [onLoad, widgetId])

  // Create theme configuration for Ant Design (desktop only)
  const antdTheme = {
    token: {
      colorPrimary: config.primaryColor || '#1677ff',
      borderRadius: 6,
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
    },
    algorithm: config.theme === 'dark' ? undefined : undefined, // We'll handle dark theme via CSS
  }

  // Error boundary-like error handling
  const handleError = (error: any) => {
    console.error('BookingWidget Error:', error)
    setError(error.message || 'An unexpected error occurred')
    onError?.(error)
  }

  // Handle booking completion
  const handleBookingComplete = (bookingData: any) => {
    try {
      onBookingComplete?.(bookingData)

      // Dispatch custom event for external listeners
      const event = new CustomEvent('bookingWidgetComplete', {
        detail: { bookingData, widgetId }
      })
      window.dispatchEvent(event)
    } catch (err) {
      handleError(err)
    }
  }

  if (error) {
    return (
      <div className="booking-widget-error">
        <h3>Widget Error</h3>
        <p>{error}</p>
        <button
          className="ant-btn ant-btn-primary"
          onClick={() => {
            setError(null)
            setIsLoaded(false)
            // Retry loading
            setTimeout(() => setIsLoaded(true), 100)
          }}
        >
          Retry
        </button>
      </div>
    )
  }

  if (!isLoaded) {
    return (
      <div className="booking-widget-loading">
        <div className="ant-spin ant-spin-spinning">
          <span className="ant-spin-dot ant-spin-dot-spin">
            <i className="ant-spin-dot-item"></i>
            <i className="ant-spin-dot-item"></i>
            <i className="ant-spin-dot-item"></i>
            <i className="ant-spin-dot-item"></i>
          </span>
        </div>
        <p style={{ marginTop: '16px', color: 'var(--bw-text-color-secondary)' }}>
          Loading booking widget...
        </p>
      </div>
    )
  }

  // Widget content component
  const WidgetContent = () => (
      <div className="booking-widget-wrapper" data-widget-id={widgetId}>
        {/* Widget Header */}
        <div className="booking-widget-header">
          <h1 style={{ fontSize: isMobile ? '24px' : '32px' }}>
            Book Your Appointment
          </h1>
          <p style={{ fontSize: isMobile ? '14px' : '16px' }}>
            Choose your service, select your preferred time, and provide your details
          </p>
        </div>

        {/* Widget Content */}
        <div className="booking-widget-content">
          {isMobile ? (
            <AppointmentBookingFormMobile
              tenantId={config.tenantId}
              apiUrl={config.apiUrl}
              onBookingComplete={handleBookingComplete}
              onError={handleError}
            />
          ) : (
            <AppointmentBookingForm
              tenantId={config.tenantId}
              apiUrl={config.apiUrl}
              onBookingComplete={handleBookingComplete}
              onError={handleError}
            />
          )}
        </div>

        {/* Toast notifications positioned relative to widget */}
        <Toaster
          position={isMobile ? "bottom-center" : "top-right"}
          expand={!isMobile}
          richColors
          closeButton
          toastOptions={{
            duration: 4000,
            className: 'booking-widget-toast',
            style: {
              fontFamily: 'var(--bw-font-family)',
            }
          }}
          visibleToasts={isMobile ? 3 : 5}
        />
      </div>
    )

  // Render with appropriate ConfigProvider based on device type
  if (isMobile) {
    return (
      <div className="booking-widget-container">
        <AntdMobileConfigProvider locale={enUSMobile}>
          <WidgetContent />
        </AntdMobileConfigProvider>
        {/* Portal container for antd-mobile popups and toasts */}
        {/* This container is reserved for future use when antd-mobile supports custom portal containers */}
        <div
          ref={portalContainerRef}
          className="booking-widget-portals"
          style={{
            position: 'relative',
            zIndex: 10000,
          }}
        />
      </div>
    )
  }

  return (
    <div className="booking-widget-container">
      <AntdConfigProvider theme={antdTheme} locale={enUS}>
        <WidgetContent />
      </AntdConfigProvider>
    </div>
  )
}

export default WidgetContainer